import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Судебная система и механизм вынесения решений","description":"","frontmatter":{},"headers":[],"relativePath":"ru/48-司法体系与裁决机制.md","filePath":"ru/48-司法体系与裁决机制.md","lastUpdated":1789183869000}'),d={name:"ru/48-司法体系与裁决机制.md"};function e(o,t,h,n,s,b){return i(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="судебная-система-и-механизм-вынесения-решении" tabindex="-1">Судебная система и механизм вынесения решений <a class="header-anchor" href="#судебная-система-и-механизм-вынесения-решении" aria-label="Permalink to &quot;Судебная система и механизм вынесения решений&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>48</td></tr><tr><td>Модуль</td><td>Правовая система и структура управления</td></tr><tr><td>Ключевые слова</td><td>Симбиотический Суд, Независимое правосудие, Многорасовое правосудие, Рассмотрение культивационных дел, Альтернативное разрешение споров</td></tr></tbody></table><h2 id="i-обзор-судебнои-системы" tabindex="-1">I. Обзор судебной системы <a class="header-anchor" href="#i-обзор-судебнои-системы" aria-label="Permalink to &quot;I. Обзор судебной системы&quot;">​</a></h2><p>Судебная система Симбиотической Цивилизации Якоря — важная часть «разделения и уравновешивания трёх властей». Симбиотический Суд независимо осуществляет судебную власть в соответствии с законом, разрешает споры между всеми жизнями во Вселенной Хэнъюань, охраняет справедливость и поддерживает симбиотический правопорядок.</p><p>Судебная система руководствуется следующими основными принципами:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Независимое правосудие</td><td>Суд независимо осуществляет судебную власть в соответствии с законом; никакая организация или лицо не может вмешиваться</td></tr><tr><td>Беспристрастное правосудие</td><td>Дела рассматриваются на основе фактов и закона; равная защита законных прав и интересов всех сторон</td></tr><tr><td>Открытое разбирательство</td><td>Судебная деятельность открыта для общества, за исключением дел, затрагивающих государственные тайны, личную жизнь и коммерческие тайны</td></tr><tr><td>Двухинстанционность</td><td>Дела рассматриваются по двухинстанционной системе; по делам первой инстанции допускается одна апелляция</td></tr><tr><td>Защита процессуальных прав</td><td>Стороны имеют право на иск, защиту, апелляцию и заявление о пересмотре</td></tr><tr><td>Многорасовое участие</td><td>Представители всех рас участвуют в правосудии, обеспечивая адаптацию правосудия к физиологическим и культурным особенностям всех рас</td></tr></tbody></table><h2 id="ii-структура-и-подсудность-судов" tabindex="-1">II. Структура и подсудность судов <a class="header-anchor" href="#ii-структура-и-подсудность-судов" aria-label="Permalink to &quot;II. Структура и подсудность судов&quot;">​</a></h2><p>Симбиотический Суд делится на несколько уровней с соответствующим разделением подсудности:</p><table tabindex="0"><thead><tr><th>Уровень суда</th><th>Название</th><th>Подсудность</th></tr></thead><tbody><tr><td>Первая инстанция</td><td>Общинный суд</td><td>Мелкие гражданские споры, мелкие споры между жителями, трудовые споры, потребительские споры</td></tr><tr><td>Вторая инстанция</td><td>Региональный суд</td><td>Гражданские, коммерческие, культивационные, административные дела обычной важности</td></tr><tr><td>Третья инстанция</td><td>Верховный Симбиотический Суд</td><td>Крупные и сложные дела, конституционные дела, межплоскостные дела, дела с участием нескольких рас</td></tr><tr><td>Специальный</td><td>Специальный суд по культивации</td><td>Культивационные дела: отклонение культивации, энергетический откат, эрозия законов, споры сект, споры о культивационных ресурсах</td></tr><tr><td>Специальный</td><td>Суд области сознания</td><td>Дела, связанные с областью сознания, духовные загрязнения, информационные преступления</td></tr><tr><td>Специальный</td><td>Военный суд</td><td>Дела военнослужащих и военно-связанной культивационной деятельности</td></tr></tbody></table><p>Верховный Симбиотический Суд также осуществляет функции унификации толкования закона, издания судебных разъяснений и надзора за нижестоящими судами.</p><h2 id="iii-механизм-вынесения-решении" tabindex="-1">III. Механизм вынесения решений <a class="header-anchor" href="#iii-механизм-вынесения-решении" aria-label="Permalink to &quot;III. Механизм вынесения решений&quot;">​</a></h2><h3 id="i-институт-многорасового-правосудия" tabindex="-1">(I) Институт многорасового правосудия <a class="header-anchor" href="#i-институт-многорасового-правосудия" aria-label="Permalink to &quot;(I) Институт многорасового правосудия&quot;">​</a></h3><p>По делам с участием особых рас применяется институт многорасового правосудия:</p><ol><li>По делам с участием одной расы в состав коллегии включаются заседатели этой расы.</li><li>По делам с участием нескольких рас включаются заседатели соответствующих рас; состав коллегии определяется по числу и сложности участвующих рас.</li><li>По делам с особыми физиологическими особенностями (такими как водные расы, энергетические существа) могут приглашаться специальные эксперты для участия в правосудии.</li><li>Вопросы доказательств и фактов, связанные с расовыми обычаями, определяются с учётом обычного права соответствующих рас.</li></ol><h3 id="ii-рассмотрение-культивационных-дел" tabindex="-1">(II) Рассмотрение культивационных дел <a class="header-anchor" href="#ii-рассмотрение-культивационных-дел" aria-label="Permalink to &quot;(II) Рассмотрение культивационных дел&quot;">​</a></h3><p>Культивационные дела отличаются высокой техничностью; механизм рассмотрения культивационных дел включает:</p><ol><li><strong>Экспертные заседатели по культивации</strong>: по делам, затрагивающим профессиональные вопросы, такие как отклонение культивации, энергетический откат и эрозия законов, в состав коллегии включаются эксперты по культивации.</li><li><strong>Определение доказательств стадии</strong>: определение стадии и силы культиватора основывается на стандартных испытательных и экспертных учреждениях.</li><li><strong>Применение культивационного права</strong>: при рассмотрении культивационных дел применяются культивационные законы и техники, сочетающие правовые положения с культивационным здравым смыслом.</li><li><strong>Особое исполнение</strong>: исполнение решений по культивационным делам может использовать такие средства, как энергетические ограничения и духовные запреты.</li></ol><h3 id="iii-институт-медиации" tabindex="-1">(III) Институт медиации <a class="header-anchor" href="#iii-институт-медиации" aria-label="Permalink to &quot;(III) Институт медиации&quot;">​</a></h3><p>Суд развивает институт медиации, поощряя стороны к разрешению споров путём медиации:</p><ul><li><strong>Досудебная медиация</strong>: по мелким спорам медиация поощряется до суда.</li><li><strong>Судебная медиация</strong>: в ходе судебного разбирательства с согласия сторон Суд может проводить медиацию.</li><li><strong>Медиация с учётом расовых особенностей</strong>: медиация уважает обычаи и привычки всех рас; в медиации могут участвовать расовые старейшины или представители этносов.</li><li><strong>Действие медиации</strong>: вступившее в силу медиативное соглашение имеет обязательную силу; при неисполнении можно подать заявление об исполнении.</li></ul><h3 id="iv-альтернативное-разрешение-споров" tabindex="-1">(IV) Альтернативное разрешение споров <a class="header-anchor" href="#iv-альтернативное-разрешение-споров" aria-label="Permalink to &quot;(IV) Альтернативное разрешение споров&quot;">​</a></h3><p>Помимо судопроизводства, устанавливаются следующие альтернативные методы разрешения споров:</p><table tabindex="0"><thead><tr><th>Метод</th><th>Содержание</th></tr></thead><tbody><tr><td>Арбитраж</td><td>Споры, по которым достигнуто соглашение об арбитраже, разрешаются арбитражным органом; арбитражное решение окончательно</td></tr><tr><td>Экспертное определение</td><td>Профессиональные споры могут определяться экспертными учреждениями</td></tr><tr><td>Симбиотическая консультация</td><td>Споры между расами или организациями разрешаются через Механизм Симбиотической Консультации</td></tr><tr><td>Медиация старейшин</td><td>По традиционным спорам особых рас может применяться медиация расовых старейшин</td></tr></tbody></table><h2 id="iv-судебная-система" tabindex="-1">IV. Судебная система <a class="header-anchor" href="#iv-судебная-система" aria-label="Permalink to &quot;IV. Судебная система&quot;">​</a></h2><h3 id="i-право-на-предъявление-иска" tabindex="-1">(I) Право на предъявление иска <a class="header-anchor" href="#i-право-на-предъявление-иска" aria-label="Permalink to &quot;(I) Право на предъявление иска&quot;">​</a></h3><p>Право на предъявление иска имеют следующие субъекты:</p><ul><li>Естественные жизни и организационные субъекты, чьи законные права и интересы нарушены</li><li>Симбиотическая прокуратура может подавать публичные иски за действия, наносящие вред общественным интересам</li><li>Законно назначенные общественные организации могут подавать публичные иски в пределах своих сфер</li></ul><h3 id="ii-система-доказательств" tabindex="-1">(II) Система доказательств <a class="header-anchor" href="#ii-система-доказательств" aria-label="Permalink to &quot;(II) Система доказательств&quot;">​</a></h3><p>Система доказательств Симбиотического Суда включает:</p><ol><li><strong>Виды доказательств</strong>: вещественные доказательства, письменные доказательства, показания свидетелей, объяснения сторон, заключения экспертиз, протоколы осмотра, доказательства области сознания и т.д.</li><li><strong>Бремя доказывания</strong>: истец несёт бремя доказывания своих требований; сторона, утверждающая благоприятный факт, несёт бремя доказывания этого факта.</li><li><strong>Энергетические доказательства</strong>: доказательства, извлечённые из области сознания и энергетических следов, должны извлекаться законно уполномоченными органами для обеспечения законности и достоверности.</li><li><strong>Межплоскостные доказательства</strong>: доказательства с участием нескольких плоскостей взаимно признаются и конвертируются механизмом межплоскостного судебного сотрудничества.</li></ol><h3 id="iii-система-исполнения" tabindex="-1">(III) Система исполнения <a class="header-anchor" href="#iii-система-исполнения" aria-label="Permalink to &quot;(III) Система исполнения&quot;">​</a></h3><p>Вступившие в силу судебные решения и определения подлежат исполнению. В отношении отказывающихся исполнять Суд может применить следующие меры принудительного исполнения:</p><ul><li>Замораживание и перевод культивационных ресурсов и имущества</li><li>Энергетические ограничения и ограничения культивации</li><li>Публичное объявление недобросовестного поведения</li><li>Содержание под стражей и другие меры принуждения (при серьёзных обстоятельствах)</li></ul><h2 id="v-судебныи-надзор" tabindex="-1">V. Судебный надзор <a class="header-anchor" href="#v-судебныи-надзор" aria-label="Permalink to &quot;V. Судебный надзор&quot;">​</a></h2><p>Для обеспечения справедливости правосудия устанавливаются следующие механизмы надзора:</p><ul><li><strong>Надзор Надзорного Комитета Якоря</strong>: Надзорный Комитет Якоря осуществляет надзор за судебной деятельностью в соответствии с законом, обеспечивая законное функционирование судебных органов.</li><li><strong>Надзор второй инстанции и пересмотра</strong>: апелляционная система и система пересмотра исправляют ошибочные решения первой инстанции.</li><li><strong>Дисциплинарный надзор</strong>: судебные работники, нарушающие дисциплину, привлекаются к дисциплинарной ответственности.</li><li><strong>Общественный надзор</strong>: общественность осуществляет надзор за судебной деятельностью через наблюдение за процессами, общественное мнение и т.д.</li></ul><h2 id="vi-межплоскостное-судебное-сотрудничество" tabindex="-1">VI. Межплоскостное судебное сотрудничество <a class="header-anchor" href="#vi-межплоскостное-судебное-сотрудничество" aria-label="Permalink to &quot;VI. Межплоскостное судебное сотрудничество&quot;">​</a></h2><p>По межплоскостным делам устанавливается механизм судебного сотрудничества:</p><ol><li>Взаимное признание судебных решений между плоскостями.</li><li>Межплоскостная помощь во вручении документов и сборе доказательств.</li><li>Межплоскостное уголовно-процессуальное сотрудничество.</li><li>Межплоскостная помощь в исполнении и обмен информацией о недобросовестном поведении.</li></ol><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p><em>Судебная система и механизм вынесения решений</em> — последний рубеж правопорядка Симбиотической Цивилизации Якоря. Создавая многоуровневую судебную систему, институт многорасового правосудия и механизм рассмотрения культивационных дел, он обеспечивает справедливость и авторитет правосудия, охраняет законные права и интересы всех жизней и предоставляет надёжные судебные гарантии для совместного продвижения Десяти Тысяч Рас.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li><li>49-治理框架与权力制衡 (Структура управления и баланс властей)</li><li>44-医疗保障法 (Закон о Гарантии Медицинского Обеспечения)</li><li>30-锚点议事会职能与议事规则 (Функции и правила заседаний Собрания Якоря)</li></ul>',43)])])}const I=a(d,[["render",e]]);export{c as __pageData,I as default};
